proposed.setup:
const seed = window.SEED.workbooks.find(function (w) { return w.id === 'wb-q3-sales'; });
const w = JSON.parse(JSON.stringify(seed));
const s = w.sheets[0];
s.validations = [
  { id: 'vr-keep', a: 'B2', b: 'B2', type: 'number', min: 0, max: 100 },
  { id: 'vr-del', a: 'B3', b: 'B3', type: 'number', min: 0, max: 100 }
];
window.__w = w;
window.__s = s;

proposed.precondition:
const s = window.__s;
assert.strictEqual(validationMessage(s, 'B2', '101'), 'Please enter a number from 0 to 100');
assert.strictEqual(validationMessage(s, 'B3', '101'), 'Please enter a number from 0 to 100');
assert.strictEqual(validationMessage(s, 'B4', '101'), null);

proposed.check:
const w = window.__w;
const s = w.sheets[0];
shiftRows(s, 2, -1);
adjustFormulas(s, 2, -1, -1, 0);
shiftRules(s, 2, -1, -1, 0);
adjustPivotRange(w, s.id, 2, -1, -1, 0);
assert.strictEqual(validationMessage(s, 'B2', '101'), 'Please enter a number from 0 to 100');
assert.strictEqual(validationMessage(s, 'B3', '101'), null);

proposed.setup:
const seed = window.SEED.workbooks.find(function (w) { return w.id === 'wb-q3-sales'; });
const w = JSON.parse(JSON.stringify(seed));
const src = w.sheets[0];
const ps = { id: 'sh-pivot-1', name: 'Pivot1', cells: {}, sel: { a: 'A1', b: 'A1' }, filters: [], filterRange: null, validations: [], pivot: { sourceId: src.id, range: { a: 'A1', b: 'B3' }, rows: 'Region', columns: '', values: 'Sales', method: 'SUM' } };
w.sheets.push(ps);
window.__w = w;
window.__s = src;
window.__p = ps;

proposed.precondition:
const res = computePivot(window.__w, window.__p);
assert.ok(res && !res.err);
assert.strictEqual(res.cells.A1, 'Region');
assert.strictEqual(res.cells.B1, 'SUM of Sales');
assert.strictEqual(res.cells.A2, 'East');
assert.strictEqual(res.cells.B2, '1200');
assert.strictEqual(res.cells.A3, 'North');
assert.strictEqual(res.cells.B3, '800');
assert.strictEqual(res.cells.A4, 'Grand Total');
assert.strictEqual(res.cells.B4, '2000');

proposed.check:
const w = window.__w;
const s = w.sheets[0];
shiftRows(s, 2, -1);
adjustFormulas(s, 2, -1, -1, 0);
shiftRules(s, 2, -1, -1, 0);
adjustPivotRange(w, s.id, 2, -1, -1, 0);
const res = computePivot(w, window.__p);
assert.ok(res && !res.err);
assert.strictEqual(res.cells.A2, 'East');
assert.strictEqual(res.cells.B2, '1200');
assert.strictEqual(res.cells.A3, 'Grand Total');
assert.strictEqual(res.cells.B3, '1200');

proposed.setup:
const seed = window.SEED.workbooks.find(function (w) { return w.id === 'wb-q3-sales'; });
const w = JSON.parse(JSON.stringify(seed));
const s = w.sheets[0];
s.filterRange = { a: 'A1', b: 'C4' };
s.filters = [{ header: 'Status', col: 2, kind: 'values', values: ['Open'] }];
window.__w = w;
window.__s = s;

proposed.precondition:
const hidden = filterHidden(window.__s);
assert.strictEqual(hidden.has(1), false);
assert.strictEqual(hidden.has(2), true);
assert.strictEqual(hidden.has(3), false);

proposed.check:
const w = window.__w;
const s = w.sheets[0];
shiftCols(s, 0, 1);
adjustFormulas(s, -1, 0, 0, 1);
shiftRules(s, -1, 0, 0, 1);
adjustPivotRange(w, s.id, -1, 0, 0, 1);
const hidden = filterHidden(s);
assert.strictEqual(hidden.has(1), false);
assert.strictEqual(hidden.has(2), true);

